function createPanelTexture(width, height, gridSpacing) {
  const textureWidth = 512;
  const textureHeight = 320;
  const data = new Uint8ClampedArray(textureWidth * textureHeight * 4);

  const gridPixels = Math.round((gridSpacing / width) * textureWidth);

  for (let y = 0; y < textureHeight; y++) {
    for (let x = 0; x < textureWidth; x++) {
      const idx = (y * textureWidth + x) * 4;

      // Radial gradient
      const u = x / textureWidth;
      const v = y / textureHeight;
      const dx = u - 0.5;
      const dy = (v - 0.5) * (textureHeight / textureWidth);
      const dist = Math.sqrt(dx * dx + dy * dy);
      const t = Math.min(1, dist * 1.8);

      const r0 = 0x14, g0 = 0x14, b0 = 0x1a;
      const r1 = 0x0b, g1 = 0x0b, b1 = 0x10;

      data[idx] = Math.round(r0 * (1 - t) + r1 * t);
      data[idx + 1] = Math.round(g0 * (1 - t) + g1 * t);
      data[idx + 2] = Math.round(b0 * (1 - t) + b1 * t);
      data[idx + 3] = 255;

      // Grid overlay (6% opacity)
      const gx = x % gridPixels;
      const gy = y % gridPixels;
      if (gx < 1 || gy < 1) {
        const gridR = 0xe8, gridG = 0xec, gridB = 0xf2;
        const gridAlpha = 0.06;
        data[idx] = Math.round(data[idx] * (1 - gridAlpha) + gridR * gridAlpha);
        data[idx + 1] = Math.round(data[idx + 1] * (1 - gridAlpha) + gridG * gridAlpha);
        data[idx + 2] = Math.round(data[idx + 2] * (1 - gridAlpha) + gridB * gridAlpha);
      }

      // Border (0.006 unit hairline)
      const borderPixels = 1;
      if (x < borderPixels || x > textureWidth - borderPixels ||
          y < borderPixels || y > textureHeight - borderPixels) {
        data[idx] = 0x26;
        data[idx + 1] = 0x26;
        data[idx + 2] = 0x2f;
      }
    }
  }

  const texture = new THREE.DataTexture(data, textureWidth, textureHeight, THREE.RGBAFormat, THREE.UnsignedByteType);
  texture.needsUpdate = true;
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearFilter;
  return texture;
}

function createGhostPreview() {
  const group = new THREE.Group();

  // Card outline (1.1w x 1.4h wireframe)
  const cardW = 1.1, cardH = 1.4;
  const cardGeometry = new THREE.BufferGeometry();
  const cardVertices = new Float32Array([
    -cardW/2, -cardH/2, 0,  cardW/2, -cardH/2, 0,
    cardW/2,  cardH/2, 0,  -cardW/2,  cardH/2, 0,
    -cardW/2, -cardH/2, 0
  ]);
  const cardIndices = new Uint16Array([0, 1, 1, 2, 2, 3, 3, 0]);
  cardGeometry.setAttribute('position', new THREE.BufferAttribute(cardVertices, 3));
  cardGeometry.setIndex(new THREE.BufferAttribute(cardIndices, 1));

  const cardMaterial = new THREE.LineBasicMaterial({ color: 0xe8ecf2, linewidth: 1, opacity: 0.3, transparent: true });
  const cardLines = new THREE.LineSegments(cardGeometry, cardMaterial);
  group.add(cardLines);

  // Dial circle (0.55 diameter)
  const dialRadius = 0.275;
  const dialGeometry = new THREE.BufferGeometry();
  const dialPoints = [];
  for (let i = 0; i <= 32; i++) {
    const angle = (i / 32) * Math.PI * 2;
    dialPoints.push(Math.cos(angle) * dialRadius, Math.sin(angle) * dialRadius, 0);
  }
  dialGeometry.setAttribute('position', new THREE.BufferAttribute(new Float32Array(dialPoints), 3));
  const dialMaterial = new THREE.LineBasicMaterial({ color: 0xe8ecf2, opacity: 0.22, transparent: true });
  const dialCircle = new THREE.Line(dialGeometry, dialMaterial);
  dialCircle.position.set(0, 0.1, 0);
  group.add(dialCircle);

  // Ghost text bars (0.7w x 0.06h, 22% opacity)
  for (let i = 0; i < 2; i++) {
    const barGeometry = new THREE.PlaneGeometry(0.7, 0.06);
    const barMaterial = new THREE.MeshBasicMaterial({ color: 0xe8ecf2, opacity: 0.22, transparent: true });
    const bar = new THREE.Mesh(barGeometry, barMaterial);
    bar.position.y = -0.35 - i * 0.1;
    group.add(bar);
  }

  return group;
}

function createButtonGradient() {
