  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 4;
      const t = y / height;

      const r0 = 0xff, g0 = 0x44, b0 = 0x50;
      const r1 = 0xc1, g1 = 0x12, b1 = 0x1f;

      data[idx] = Math.round(r0 * (1 - t) + r1 * t);
      data[idx + 1] = Math.round(g0 * (1 - t) + g1 * t);
      data[idx + 2] = Math.round(b0 * (1 - t) + b1 * t);
      data[idx + 3] = 255;
    }
  }

  const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat, THREE.UnsignedByteType);
  texture.needsUpdate = true;
  return texture;
}
